#[verus::spec]
fn square_elements(a: Vec<i32>) -> Vec<i32> {
    // Precondition: The input vector must not be empty.
    // This is a simple requirement for the sake of the example.
    // You can adjust this based on your actual requirements.
    requires(!a.is_empty());

    // The output vector will have the same length as the input vector.
    // This is an invariant that we will ensure.
    let result: Vec<i32> = a.iter().map(|&x| x * x).collect();

    // Postcondition: The output vector must have the same length as the input vector.
    ensures(result.len() == a.len());

    // Postcondition: Each element in the output vector is the square of the corresponding element in the input vector.
    ensures(result.iter().zip(a.iter()).all(|(r, &x)| *r == x * x));

    result
}